import os

UI_DIR = os.path.join("src", "web", "ui")
DELIMITER = ')rawliteral"'


def read(name):
    with open(os.path.join(UI_DIR, name), encoding="utf-8") as f:
        return f.read()


def build_page():
    page = read("index.html")
    page = page.replace("@@STYLE@@", read("style.css"))
    page = page.replace("@@SCRIPT@@", read("app.js"))
    if DELIMITER in page:
        raise SystemExit("src/web/ui contains " + DELIMITER)
    return page


def render_header(page):
    return (
        "// Generated by scripts/embed_ui.py from src/web/ui/. Do not edit.\n"
        "#pragma once\n"
        'static const char kIndexHtml[] PROGMEM = R"rawliteral(' + page + DELIMITER + ";\n"
    )


def write_if_changed(path, text):
    # Unchanged content keeps the file's mtime so ccache/SCons don't rebuild.
    if os.path.exists(path):
        with open(path, encoding="utf-8") as f:
            if f.read() == text:
                return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)


try:
    Import("env")  # noqa: F821 -- provided by PlatformIO/SCons
except NameError:
    env = None

if env is not None:
    gen_dir = os.path.join(env.subst("$BUILD_DIR"), "ui_gen")
    write_if_changed(os.path.join(gen_dir, "ui_page.h"), render_header(build_page()))
    env.Append(CPPPATH=[gen_dir])
